solutions.naive:
class Solution:
    def findNthDigit(self, n: int) -> int:
        length = 1
        start = 1
        while n > 9 * start * length:
            n -= 9 * start * length
            length += 1
            start *= 10
        number = start + (n - 1) // length
        return int(str(number)[(n - 1) % length])

